# Let's manually examine the input/output pairs
inputs = ['kfka', 'ciegyk', 'hhekh', 'ece', 'ui']
outputs = ['kfka', 'djegyk', 'hhekh', 'ece', 'uyu']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, out in enumerate(outputs):
    print(f"  {i}: '{out}'")

print("\nDifferences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"  {i}: '{inp}' -> '{out}'")

